#pragma once
static void testTail(const juce::File& root){
 auto base=root.getChildFile("tail");base.createDirectory();juce::VST3PluginFormat format;juce::OwnedArray<juce::PluginDescription> types;
 format.findAllTypesForFile(types,juce::File(STUDIO_SOURCE_ROOT).getChildFile("build/backend/StudioTestTail_artefacts/Release/VST3/Studio Test Tail.vst3").getFullPathName());require(types.size()==1,"Tail fixture scan failed");
 auto source=base.getChildFile("source.wav");juce::AudioBuffer<float> input(2,24000);input.clear();input.setSample(0,12000,0.001f);input.setSample(1,16000,-0.002f);
 juce::WavAudioFormat wav;std::unique_ptr<juce::AudioFormatWriter> writer(wav.createWriterFor(source.createOutputStream().release(),48000,2,32,{},0));require(writer&&writer->writeFromAudioSampleBuffer(input,0,24000),"Tail source write failed");writer.reset();
 float error=0;int cases=0;int editorCycles=0;juce::Array<juce::var> alignments;
 auto expected=[](int c,int i){return c==0?(i==12000?0.001f:(i==36000?0.0005f:0)):(i==16000?-0.002f:(i==40000?-0.001f:0));};
 for(int block:{128,256}){
  juce::String loadError;auto direct=format.createInstanceFromDescription(*types[0],48000,block,loadError);require(direct!=nullptr,"Direct tail load failed");for(int cycle=0;cycle<2;++cycle){std::unique_ptr<juce::AudioProcessorEditor> editor(direct->createEditorIfNeeded());require(editor!=nullptr&&editor->getWidth()>0&&editor->getHeight()>0,"Fixture editor creation failed");editor.reset();require(direct->getActiveEditor()==nullptr,"Editor did not detach");++editorCycles;}
  direct->setRateAndBufferSizeDetails(48000,block);direct->prepareToPlay(48000,block);require(std::abs(direct->getTailLengthSeconds()-0.5)<1e-8&&direct->getLatencySamples()==0,"Tail metadata differs");
  for(int at=0;at<48000;at+=block){int n=std::min(block,48000-at);juce::AudioBuffer<float> audio(2,n);audio.clear();for(int c=0;c<2;++c)for(int i=0;i<n;++i)if(at+i<24000)audio.setSample(c,i,input.getSample(c,at+i));juce::MidiBuffer midi;direct->processBlock(audio,midi);for(int c=0;c<2;++c)for(int i=0;i<n;++i)error=std::max(error,std::abs(audio.getSample(c,i)-expected(c,at+i)));}direct->releaseResources();require(error<1e-7f,"Direct tail differs");++cases;
  auto dir=base.getChildFile(juce::String(block));dir.createDirectory();Session s(dir);s.importAudio(source,0,0);s.engine.getPluginManager().initialise();s.engine.getPluginManager().knownPluginList.addType(*types[0]);
  auto item=s.edit->getPluginCache().createNewPlugin(te::ExternalPlugin::xmlTypeName,*types[0]);auto* external=dynamic_cast<te::ExternalPlugin*>(item.get());require(external!=nullptr,"Engine tail creation failed");s.trackAt(0).pluginList.insertPlugin(item,0,nullptr);external->initialiseFully();require(external->getAudioPluginInstance()!=nullptr,"Engine tail load failed");
  auto output=dir.getChildFile("offline.wav");s.render(output,block);auto offline=readWave(output);for(int c=0;c<2;++c)for(int i=0;i<48000;++i)error=std::max(error,std::abs(offline.getSample(c,i)-expected(c,i)));require(error<1e-7f,"Engine offline tail differs");++cases;
  s.save();item=nullptr;s.edit.reset();auto& hosted=s.engine.getDeviceManager().getHostedAudioDeviceInterface();te::HostedAudioDeviceInterface::Parameters params;params.sampleRate=48000;params.blockSize=block;params.inputChannels=0;params.outputChannels=2;hosted.initialise(params);hosted.prepareToPlay(48000,block);
  auto xml=juce::XmlDocument::parse(s.projectFile);require(xml!=nullptr,"Tail live state missing");te::Edit::Options options{s.engine,juce::ValueTree::fromXml(*xml),te::ProjectItemID::createNewID(0)};options.role=te::Edit::forEditing;options.numAudioTracks=0;options.editFileRetriever=[&s]{return s.projectFile;};s.edit=std::make_unique<te::Edit>(options);
  juce::AudioBuffer<float> audio(2,block),captured(2,48000+block*8);captured.clear();juce::MidiBuffer midi;
  for(int i=0;i<10;++i){audio.clear();midi.clear();hosted.processBlock(audio,midi);juce::MessageManager::getInstance()->runDispatchLoopUntil(1);}
  auto& transport=s.edit->getTransport();transport.setPosition(Session::time(0));transport.play(false);
  for(int at=0;at+block<=captured.getNumSamples();at+=block){audio.clear();midi.clear();hosted.processBlock(audio,midi);for(int c=0;c<2;++c)captured.copyFrom(c,at,audio,c,0,block);juce::MessageManager::getInstance()->runDispatchLoopUntil(1);}transport.stop(false,true);
  int first=-1;for(int i=0;i<captured.getNumSamples();++i)if(std::abs(captured.getSample(0,i))>1e-5f){first=i;break;}require(first>=0,"Hosted tail source missing");int shift=first-12000;alignments.add(shift);require(std::abs(shift)<=block*2,"Hosted alignment exceeds two blocks");
  for(int c=0;c<2;++c)for(int i=0;i<48000;++i){int at=i+shift;require(at>=0&&at<captured.getNumSamples(),"Hosted capture range insufficient");error=std::max(error,std::abs(captured.getSample(c,at)-offline.getSample(c,i)));}require(error<1e-7f,"Hosted/offline tail differs");++cases;
 }
 auto* report=new juce::DynamicObject;juce::var value(report);report->setProperty("cases",cases);report->setProperty("editor_lifecycle_cycles",editorCycles);report->setProperty("max_error",error);report->setProperty("hosted_alignment_samples",alignments);report->setProperty("tail_seconds",0.5);report->setProperty("physical_device_opened",false);base.getChildFile("tail-result.json").replaceWithText(juce::JSON::toString(value));
}
